217		}
218	}
219	
220	// 保留首次触发截止处理的行为：活动仍在执行时，已领取操作第一次在截止时刻提交，
221	// 仍把未结束设备记为超时、以本次时间结束活动；这次推进的时间仍参与倒退判断。
222	// 此后第二次迟到提交才是不推进基线的纯拒绝。
223	func TestFirstDeadlineSubmissionStillAdvancesTime(t *testing.T) {
