var op *Operation
var reject error
err = s.commit(func() error {
	// 活动已经结束（截止超时，或截止前已全部成功/失败结束）：纯拒绝。
	// 即使本次领取时间达到或晚于截止时间，即使查询的设备此前已领取
	// 下载/安装/回滚但未完成，也不返回任何操作，不推进时间基线，
	// 不改结束时间、活动结论、设备状态与状态时间、结果历史和影子，
	// 否则随后原本合法的时间会因这次拒绝而被判为倒退。
	if c.Ended {
		reject = ErrCampaignEnded
		return nil
	}
	// 活动仍在执行且时间首次到达截止：不派发操作，未结束设备全部
	// 超时（等待/正在回滚的记回滚超时），已有终态保持不变，以本次
	// 领取时间结束活动。即使查询的设备早已成功，其他未结束设备仍要
	// 级联超时；本次确实推进的时间仍参与后续倒退判断。
	if !at.Before(c.Deadline) {
		c.LastTime = at
		s.applyTimeout(c, at)
		reject = ErrCampaignEnded
		return nil
	}
	if isTerminal(cd.Status) {
		reject = fmt.Errorf("%w: %s", ErrDeviceFinished, deviceID)
		return nil
	}
	c.LastTime = at
	// 已领取但未完成的操作：查询仍返回原标识，不要求在线或位于窗口内。
	if out := outstandingOp(c, cd); out != nil {
		op = out
		return nil
	}
	// 安装失败已接受、等待回滚：回滚是该设备的善后操作，不受批次放行影响。
	// 首次领取要求在线且位于原维护窗口 [start,end) 内；离线或窗口外保留待办。
	if cd.Status == DeviceAwaitingRollback {
		if !s.devices[deviceID].Online {
			return nil
		}
		if at.Before(c.WindowStart) || !at.Before(c.WindowEnd) {
			return nil
